    const libraryStyle=el('style');libraryStyle.textContent='#skill-library-picker input[type=search]{display:block;width:100%;margin-top:5px}#skill-library-results{display:grid;gap:4px;max-height:240px;overflow:auto}#skill-library-results button{text-align:left}#skill-library-preview{margin:12px 0;overflow-wrap:anywhere}#skill-library-preview p{line-height:1.7}.skill-library-values{display:grid;grid-template-columns:80px 1fr;gap:5px 8px;font-size:12px}.skill-library-values dt{color:#b9c5d8}.skill-library-values dd{margin:0}.skill-library-icon{display:inline-block;width:40px;height:40px;flex:0 0 40px;border-radius:5px;background-color:#172334;background-repeat:no-repeat;background-size:40px 40px}.library-binding{font-size:12px;line-height:1.7;color:#d4e4f6}.rule>summary{display:grid;grid-template-columns:minmax(0,1fr) 32px;gap:4px 9px;align-items:center}.rule>summary>span:first-child{overflow-wrap:anywhere}.rule-summary-meta{grid-column:1;color:#b9c5d8;font-size:12px;font-weight:400}.rule>summary>.skill-library-icon{grid-column:2;grid-row:1/3}.rule-advanced{margin:10px 0}.rule-advanced>summary{font-size:12px;font-weight:500}@media(max-width:600px){#skill-library-picker input[type=search],#skill-library-picker select{font-size:16px}}';section.append(libraryStyle);
