        rule.range??={min:null,max:null};field(grid,'目标距离上限',rule.range.max,v=>{rule.range.max=v;summaryText();},'number',{min:0,max:200,step:0.1});const enabled=el('div');row.append(enabled);check(enabled,'启用规则',rule.enabled,v=>{rule.enabled=v;summaryText();});
        const advanced=el('details');advanced.className='rule-advanced';advanced.append(el('summary','高级条件'));row.append(advanced);const advancedGrid=el('div');advancedGrid.className='rule-fields';advanced.append(advancedGrid);for(const label of Array.from(grid.children)){if(label.querySelector('input')?.getAttribute('aria-label')!=='技能按键（1–9）')advancedGrid.append(label);}
        const comboLabel=el('label','何时使用'),simpleCombo=el('select');simpleCombo.setAttribute('aria-label','连击条件');const simpleValue=!rule.combo?'any':rule.combo.min===5&&rule.combo.max===5?'full':rule.combo.min===0&&rule.combo.max===4?'building':'custom';for(const [v,t]of [['any','不限制连击点'],['building','连击点未满 5 时'],['full','连击点满 5 时'],...(simpleValue==='custom'?[['custom','自定义条件（见高级）']]:[])]){const option=el('option',t);option.value=v;simpleCombo.append(option);}simpleCombo.value=simpleValue;simpleCombo.onchange=()=>{if(simpleCombo.value==='custom')return;rule.combo=simpleCombo.value==='any'?null:simpleCombo.value==='full'?{min:5,max:5,allowUnknown:false}:{min:0,max:4,allowUnknown:true};rule.oncePerCombo=simpleCombo.value==='full';draw();};comboLabel.append(simpleCombo);grid.append(comboLabel);
