        const comboRange=rule.combo||{min:null,max:null,allowUnknown:false};function setCombo(k,v){comboRange[k]=v;rule.combo=comboRange.min==null&&comboRange.max==null&&!comboRange.allowUnknown?null:comboRange;summaryText();}
        field(advancedGrid,'连击点下限',comboRange.min,v=>setCombo('min',v),'number',{min:0,max:5});field(advancedGrid,'连击点上限',comboRange.max,v=>setCombo('max',v),'number',{min:0,max:5});
        const checks=el('div');checks.className='rule-checks';advanced.append(checks);check(checks,'允许未知连击点（仅适合攒点技能）',comboRange.allowUnknown,v=>setCombo('allowUnknown',v));check(checks,'必须已确认冷却就绪',rule.requireCooldown,v=>rule.requireCooldown=v);check(checks,'同一目标同一连击点只释放一次',rule.oncePerCombo,v=>rule.oncePerCombo=v);if(Number.isInteger(rule.librarySpellId))check(checks,'允许未知资源继续（尚未验证法力/怒气，谨慎启用）',rule.allowUnknownResource,v=>rule.allowUnknownResource=v);
